function sanitizeSeed(value){const seed=Number(value)>>>0;return seed||0x6d2b79f5}
function freshSeed(){try{const value=new Uint32Array(1);crypto.getRandomValues(value);return sanitizeSeed(value[0])}catch{return sanitizeSeed(Date.now()^Math.floor(performance.now()*1000))}}
