function snowSurface(){const override=window.AlpinePro?.settings?.condition||'auto',run=RUNS[routeIndex][runIndex],progress=Math.max(0,Math.min(1,distance/courseLength));if(override==='auto'&&liveSnowReport?.routeIndex===routeIndex){if(liveSnowReport.fresh>=3)return'POWDER';if(liveSnowReport.temp>=3)return'SPRING SLUSH';if(liveSnowReport.temp<=-8)return'PACKED ICE'}const weather=override==='auto'?ROUTES[routeIndex].weather:override;if(weather==='storm'){if(progress>.7)return'PACKED ICE';if(progress>.34)return'WHITEOUT';return'POWDER'}if(weather==='night')return'NIGHT GROOM';if(weather==='ice')return'PACKED ICE';if(weather==='powder')return'POWDER';if(weather==='groomed')return'GROOMED';if(run.terrain==='moguls')return'MOGULS';if(run.terrain==='glades'||run.terrain==='aspen')return progress>.58?'TRACKED POWDER':'POWDER';if(run.terrain==='steep'||run.terrain==='spine'||run.terrain==='alpine')return progress>.62?'PACKED ICE':'HARDPACK';if(run.terrain==='groomer')return progress>.72?'SPRING SLUSH':'GROOMED';return'GROOMED'}
