function syncTrailAccess(){trailAccessState=liveSnowReport?.routeIndex===routeIndex&&liveSnowReport.wind>=75?'closed':'open';const button=$('startButton');if(!button)return;const closed=trailAccessState==='closed';button.disabled=closed;button.setAttribute('aria-disabled',String(closed));button.setAttribute('aria-label',closed?'Patrol hold: this line is temporarily closed':'Drop in on the selected line');button.classList.toggle('trail-closed',closed);const label=button.querySelector('b');if(label)label.textContent=closed?'PATROL HOLD':'DROP IN'}
