function beginCountdown(){stopSelectionRefresh();paintDropBriefing();syncTrailAccess();if(trailAccessState==='closed'){toast('PATROL HOLD','WIND TOO STRONG FOR THIS LIFT');return}hide(ui.routes);hide(ui.results);ui.routeName.textContent=`${ROUTES[routeIndex].name} · ${RUNS[routeIndex][runIndex].name}`;if(liveSnowReport?.routeIndex===routeIndex)toast('MORNING BRIEFING',snowSurface()==='POWDER'?'POWDER FLOAT RECOMMENDED':snowSurface()==='PACKED ICE'?'EDGE GRIP RECOMMENDED':'FRESH LINE · WATCH THE WEATHER');show(ui.countdown);state='countdown';let n=3;ui.countdownValue.textContent=n;const tick=setInterval(()=>{n--;ui.countdownValue.style.animation='none';void ui.countdownValue.offsetWidth;ui.countdownValue.style.animation='';if(n>0){ui.countdownValue.textContent=n;beep(260+n*90,.07)}else if(n===0){ui.countdownValue.textContent='GO';beep(640,.15)}else{clearInterval(tick);hide(ui.countdown);startRun()}},700)}
function quickDrop(){
  routeIndex=0;runIndex=0;enterRoutes();
  const mode=$('modeSelect'),difficulty=$('difficultySelect'),condition=$('conditionSelect');
  if(mode){mode.value='training';AlpinePro.setSetting('mode','training')}
  if(difficulty){difficulty.value='beginner';AlpinePro.setSetting('difficulty','beginner')}
  if(condition){condition.value='auto';AlpinePro.setSetting('condition','auto')}
  populateRuns();$('runSelect').value='0';updatePreview();toast('QUICK DROP','HOLLYWOOD · BEGINNER TRAINING');beginCountdown();
}
