function beep(freq,duration,type='triangle',volume=.045){if(!sound)return;if(window.AlpineRushAudio){window.AlpineRushAudio.tone(freq,duration,type,volume);return}try{const ac=beep.ac||(beep.ac=new(window.AudioContext||window.webkitAudioContext)());ac.resume?.().catch(()=>{});const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(freq,ac.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(40,freq*.72),ac.currentTime+duration);g.gain.setValueAtTime(volume,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
function jump(){if(state==='title'){window.AlpineRushAudio?.intro?.();enterRoutes();return}if(state==='select'){beginCountdown();return}if(state==='over'){beginCountdown();return}if(state==='playing'&&player.jump===0){if(AlpinePro.weeklyModifier().id==='no-jump'){toast('NO JUMP WEEK','KEEP IT GROUNDED');beep(160,.08);return}const rider=RIDER_PROFILES[riderType]||RIDER_PROFILES.skier;Object.assign(player,{jumpV:(580+speed*45)*rider.air,jump:.1,spin:0,spinV:0,flip:0,flipV:0,grabTime:0,trickActive:false,compression:.85});jumps++;burst(player.x*W,player.y*H+25,'#effcff',8);beep(480,.12)}}
function trickLabel(){const degrees=Math.round(Math.abs(player.spin)*180/Math.PI/90)*90,flipProgress=Math.abs(player.flip)/(Math.PI*2),flipName=player.flip<0?'FRONTFLIP':'BACKFLIP',parts=[];if(degrees)parts.push(`${degrees}° ${player.spin<0?'LEFT':'RIGHT'}`);if(flipProgress>.12)parts.push(flipProgress>1.5?`DOUBLE ${flipName}`:flipName);if(player.grabTime>.18)parts.push(riderType==='snowboarder'?'INDY GRAB':'SAFETY GRAB');return parts.join(' + ')||'SETTING UP'}
