function toast(label,value=''){ui.toast.querySelector('small').textContent=label;ui.toast.querySelector('strong').textContent=value;ui.toast.classList.add('show');const announcer=$('importantAnnouncer'),important=['RUN OVER','FINISH LINE','PATROL HOLD','BADGE EARNED','CAREER LEVEL UP','NEW PERSONAL BEST','RIVAL CAMPAIGN','LEGENDARY CHALLENGE'].some(key=>String(label).includes(key));if(announcer&&important)announcer.textContent=value?`${label}: ${value}`:label;clearTimeout(toast.t);toast.t=setTimeout(()=>ui.toast.classList.remove('show'),850)}
function scorePop(points,x,y,label){score+=points;popups.push({x,y,text:`+${points}`,label,life:1});ui.scoreDelta.textContent=`+${points}`;ui.scoreDelta.classList.remove('pop');void ui.scoreDelta.offsetWidth;ui.scoreDelta.classList.add('pop')}
