$('soundButton').onclick=e=>{sound=!sound;store.set('alpineRushSound',sound?'on':'off');e.currentTarget.setAttribute('aria-pressed',String(sound));e.currentTarget.setAttribute('aria-label',sound?'Mute sound':'Enable sound');e.currentTarget.querySelector('span').textContent=sound?'◖))':'◖×'};$('soundButton').querySelector('span').textContent=sound?'◖))':'◖×';
window.AlpineRushInput?.onAction(({action,pressed,value})=>{if(action==='carve'){keys.left=value<-.12;keys.right=value>.12;return}if(['left','right','spinL','spinR','frontFlip','backFlip','grab'].includes(action)){keys[action]=pressed;return}if(!pressed)return;if(action==='jump')jump();if(action==='boost')activateBoost();if(action==='pause'&&['playing','paused'].includes(state))togglePause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')togglePause()});

function courseSample(progress){const points=RUNS[routeIndex][runIndex].line,p=Math.max(0,Math.min(1,progress));let b=points.findIndex(point=>point[0]>=p);if(b<1)b=1;const a=b-1,left=points[a],right=points[Math.min(b,points.length-1)],span=right[0]-left[0]||1,t=(p-left[0])/span;return{center:left[1]+(right[1]-left[1])*t,width:left[2]+(right[2]-left[2])*t}}
