function drawPlayer(){const x=player.x*W,terrainBob=player.jump===0?Math.sin(sceneryOffset*8)*1.2:0,y=player.y*H-player.jump+terrainBob;if(player.invincible>0&&player.crash===0&&Math.floor(player.invincible*12)%2===0)return;ctx.save();ctx.translate(x,y);const shadowAlpha=Math.max(.045,.24-player.jump/600),shadowWidth=30+player.jump*.07;ctx.fillStyle=`rgba(14,52,67,${shadowAlpha})`;ctx.beginPath();ctx.ellipse(0,player.jump+34,shadowWidth,7+player.jump*.025,0,0,Math.PI*2);ctx.fill();if(player.crash>0){ctx.rotate((1-player.crash/.68)*2.4+1.1);ctx.scale(1.12,.72)}else if(player.jump>0){ctx.rotate(player.spin);ctx.scale(1,Math.cos(player.flip));if(player.grabTime>.04){ctx.translate(0,5);ctx.rotate(.12)}}drawRider();ctx.restore()}
function drawSpeedStreaks(){const intensity=Math.max(0,Math.min(1,(speed-1.35)/2.2));if(intensity<=0)return;ctx.save();ctx.globalAlpha=.08+intensity*.13;ctx.strokeStyle='#f6fdff';ctx.lineWidth=1+intensity*2;for(let i=0;i<14;i++){const x=((i*83+sceneryOffset*120)% (W+80))-40;const y=H*.48+((i*47+sceneryOffset*210)%(H*.62));ctx.beginPath();ctx.moveTo(W*.5+(x-W*.5)*.12,H*.47);ctx.lineTo(x,y);ctx.stroke()}ctx.restore()}
