drawNaturalBoundaries=function(){const slices=[];for(let i=0;i<=24;i++){const t=i/24,ahead=(1-t)*courseLength*.22,s=courseSample((distance+ahead)/courseLength),camera=t*t;slices.push({x:(s.center*(1-camera)+.5*camera)*W,y:H*(.42+t*.62),half:W*(.02+t*(s.width*.9)),t})}ctx.save();ctx.lineCap='round';for(const side of [-1,1]){ctx.strokeStyle='rgba(21,61,70,.46)';ctx.lineWidth=6;ctx.beginPath();slices.forEach((s,i)=>i?ctx.lineTo(s.x+side*s.half,s.y):ctx.moveTo(s.x+side*s.half,s.y));ctx.stroke();ctx.strokeStyle=side<0?'rgba(239,117,82,.78)':'rgba(101,207,216,.78)';ctx.lineWidth=2;ctx.beginPath();slices.forEach((s,i)=>i?ctx.lineTo(s.x+side*s.half,s.y):ctx.moveTo(s.x+side*s.half,s.y));ctx.stroke()}for(const row of [5,10,15,20]){const s=slices[row],poleH=10+s.t*28;for(const side of [-1,1]){const x=s.x+side*(s.half+7+s.t*6);ctx.strokeStyle='rgba(23,54,63,.68)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,s.y+1);ctx.lineTo(x,s.y-poleH);ctx.stroke();ctx.fillStyle=side<0?'rgba(255,108,78,.88)':'rgba(106,216,224,.88)';ctx.fillRect(x-2,s.y-poleH,4,6)}}ctx.restore()};
