/* Desktop presentation: remove the painted corridor and use only restrained piste markers. */
function drawDesktopPisteMarkers(){const slices=[];for(let i=0;i<=18;i++){const t=i/18,ahead=(1-t)*courseLength*.22,s=courseSample((distance+ahead)/courseLength),camera=t*t;slices.push({x:(s.center*(1-camera)+.5*camera)*W,y:H*(.42+t*.62),half:W*(.02+t*(s.width*.9)),t})}ctx.save();for(const row of [5,9,13,17]){const s=slices[row],poleH=10+s.t*25;for(const side of [-1,1]){const x=s.x+side*(s.half+8+s.t*6);ctx.strokeStyle='rgba(21,55,64,.62)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,s.y);ctx.lineTo(x,s.y-poleH);ctx.stroke();ctx.fillStyle=side<0?'rgba(239,117,82,.82)':'rgba(101,207,216,.82)';ctx.fillRect(x-2,s.y-poleH,4,6)}}ctx.restore()}
