/* Shared piste traffic and terrain bumps: riders travel with the mountain, not toward the camera. */
const downhillSpawn=spawn;spawn=function(){downhillSpawn();if(state!=='playing')return;const sample=courseSample(Math.min(1,(distance+courseLength*.18)/courseLength));if(spawnCount%5===0){obstacles.push({type:'pisteRider',x:Math.max(.12,Math.min(.88,sample.center+(Math.random()-.5)*sample.width*.72)),y:.06+Math.random()*.08,wobble:Math.random()*6.28,hit:false,cleared:false,color:Math.random()>.5?'#5ec8dc':'#f28b55',side:Math.random()>.5?1:-1,laneV:(Math.random()>.5?1:-1)*(.012+Math.random()*.018),pace:.9+Math.random()*.16})}if(spawnCount%4===0&&['groomer','moguls','steep','bowl'].includes(RUNS[routeIndex][runIndex].terrain)){obstacles.push({type:'pisteBump',x:Math.max(.12,Math.min(.88,sample.center+(Math.random()-.5)*sample.width*.55)),y:.045,wobble:Math.random()*6.28,hit:false,cleared:false,color:'#d7edf0',side:1,laneV:0})}};
const downhillObstacleDraw=drawObstacle;drawObstacle=function(o){if(o.type==='pisteRider'){const t=Math.max(0,Math.min(1,(o.y-.4)/.48)),scale=.2+t*.95;ctx.save();ctx.translate(o.x*W,o.y*H);ctx.scale(scale,scale);drawSkier(0,0,Math.sin(o.wobble+o.y*8)*.18,o.color,false);ctx.restore();return}if(o.type==='pisteBump'){const t=Math.max(0,Math.min(1,(o.y-.4)/.48));ctx.save();ctx.translate(o.x*W,o.y*H);ctx.scale(.45+t*.75,.45+t*.75);ctx.fillStyle='rgba(46,91,103,.22)';ctx.beginPath();ctx.ellipse(0,14,30,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9eef1';ctx.beginPath();ctx.ellipse(0,0,25,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(255,255,255,.65)';ctx.beginPath();ctx.ellipse(-7,-4,12,5,-.2,0,Math.PI*2);ctx.fill();ctx.restore();return}downhillObstacleDraw(o)};
const downhillHit=hitObstacle;hitObstacle=function(o,dx){if(o.type==='pisteBump'){if(o.hit)return;o.hit=true;Object.assign(player,{jumpV:430+speed*30,jump:.08,compression:.95,spin:0,flip:0});jumps++;scorePop(120*combo,o.x*W,o.y*H-18,'MOGUL POP');burst(o.x*W,o.y*H,'#effcff',10);beep(420,.1);return}downhillHit(o,dx)};
const sharedPisteUpdate=update;update=function(dt){sharedPisteUpdate(dt);if(state!=='playing')return;obstacles.forEach(o=>{if(o.type!=='pisteRider')return;o.y-=dt*(.22+o.pace*.05)*speed;o.x+=o.laneV*dt*speed;if(o.x<.12||o.x>.88){o.x=Math.max(.12,Math.min(.88,o.x));o.laneV*=-1}o.wobble+=dt*2});};
/* Forward chase camera: the rider advances down the visible piste instead of staying pinned in one spot. */
const forwardReset=reset;reset=function(){forwardReset();player.y=.61};const forwardUpdate=update;update=function(dt){forwardUpdate(dt);if(state!=='playing')return;const progress=Math.min(1,Math.max(0,distance/courseLength)),targetY=.61+progress*.18;player.y+=(targetY-player.y)*Math.min(1,dt*3.8);cameraY+=((progress*.9)-cameraY)*dt*1.8};
/* World-space piste riders: z is downhill distance, x is lane position, and projection follows the piste curve. */
const worldTraffic=[];const worldTrafficReset=reset;reset=function(){worldTrafficReset();worldTraffic.length=0};const worldTrafficSpawn=spawn;spawn=function(){worldTrafficSpawn();if(state!=='playing'||spawnCount%4!==0)return;const z=260+Math.random()*260;worldTraffic.push({z,lane:.5+(Math.random()-.5)*.5,speed:.72+Math.random()*.32,laneSpeed:(Math.random()>.5?1:-1)*(.012+Math.random()*.012),color:Math.random()>.5?'#5ec8dc':'#f28b55',tilt:0})};
const worldTrafficUpdate=update;update=function(dt){worldTrafficUpdate(dt);if(state!=='playing')return;for(let i=worldTraffic.length-1;i>=0;i--){const rider=worldTraffic[i],relative=Math.max(.18,speed-rider.speed*.72);rider.z-=relative*dt*48;rider.lane+=rider.laneSpeed*dt;if(rider.lane<.14||rider.lane>.86){rider.lane=Math.max(.14,Math.min(.86,rider.lane));rider.laneSpeed*=-1}const sample=courseSample(Math.min(1,(distance+rider.z)/courseLength)),x=sample.center+(rider.lane-.5)*sample.width*.72;if(rider.z<48&&Math.abs(x-player.x)<.065&&player.jump<38){crashPlayer('RIDER MERGE');worldTraffic.splice(i,1);continue}if(rider.z< -35||rider.z>700)worldTraffic.splice(i,1)}};
const worldTrafficDraw=draw;draw=function(){worldTrafficDraw();if(!['playing','countdown'].includes(state))return;const visible=worldTraffic.slice().sort((a,b)=>b.z-a.z);for(const rider of visible){if(rider.z<0||rider.z>620)continue;const depth=1-rider.z/620,sample=courseSample(Math.min(1,(distance+rider.z)/courseLength)),x=sample.center+(rider.lane-.5)*sample.width*.72,y=H*(.4+depth*.58),scale=.12+depth*.96;ctx.save();ctx.translate(x*W,y);ctx.scale(scale,scale);drawSkier(0,0,rider.laneSpeed*3,rider.color,false);ctx.restore()}};
/* Grounded rider pass: stronger downhill stance, edge contact, and anchored snow interaction. */
const groundedRiderDraw=drawPlayer;drawPlayer=function(){groundedRiderDraw();if(player.jump!==0||state!=='playing')return;const x=player.x*W,y=player.y*H+38,edge=Math.max(-1,Math.min(1,player.edge)),lean=Math.abs(edge);ctx.save();ctx.globalAlpha=.2+.12*lean;ctx.strokeStyle='#244e5c';ctx.lineWidth=2;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x-7-edge*8,y);ctx.lineTo(x-16-edge*18,y+18);ctx.moveTo(x+7-edge*8,y);ctx.lineTo(x+16-edge*18,y+18);ctx.stroke();ctx.globalAlpha=.1+.14*lean;ctx.strokeStyle='#f4fcfd';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x-9-edge*8,y+2);ctx.lineTo(x-18-edge*18,y+20);ctx.moveTo(x+9-edge*8,y+2);ctx.lineTo(x+18-edge*18,y+20);ctx.stroke();if(lean>.35){ctx.globalAlpha=.35;ctx.fillStyle='#fff';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(x-Math.sign(edge)*(16+i*8)+Math.random()*8,y+8+i*5,1.5+i*.4,0,Math.PI*2);ctx.fill()}}ctx.restore()};
const stanceRiderDraw=drawRider;drawRider=function(){ctx.translate(0,-11);ctx.rotate(.09+player.vx*.035);stanceRiderDraw()};
/* Shared rider/piste projection: the rider’s feet and the visible snow use one ground point. */
function projectRiderPiste(){const progress=Math.min(1,Math.max(0,distance/courseLength)),t=.64+progress*.1,s=courseSample(Math.min(1,(distance+courseLength*(1-t)*.22)/courseLength));return{center:s.center,width:s.width,groundY:H*(.42+t*.62)}}
