function worldPisteProjection(ahead=0,lane=0){const lookAhead=Math.max(0,ahead),t=Math.max(0,Math.min(1,1-lookAhead/(courseLength*.22))),sample=courseSample(Math.min(1,(distance+lookAhead)/courseLength)),groundY=H*(.42+t*.62),laneX=sample.center+lane*sample.width*.72;return{x:laneX,y:groundY,width:sample.width,t,slope:sample.center-(courseSample(Math.min(1,(distance+lookAhead+.02*courseLength)/courseLength)).center)}}
projectRiderPiste=function(){const progress=Math.min(1,Math.max(0,distance/courseLength)),ahead=courseLength*(.22-(.1+progress*.1)),p=worldPisteProjection(ahead,player.x-courseSample(distance/courseLength).center);return{center:p.x,width:p.width,groundY:p.y}};
