/* Natural desktop piste surface: soft snow shading and banks, without a painted street track. */
function drawNaturalPisteSurface(){const slices=[];for(let i=0;i<=22;i++){const t=i/22,ahead=(1-t)*courseLength*.22,s=courseSample(Math.min(1,(distance+ahead)/courseLength));slices.push({x:(s.center*(1-t*t)+.5*t*t)*W,y:H*(.42+t*.62),half:W*(.02+t*s.width*.9),t})}ctx.save();const snow=ctx.createLinearGradient(0,H*.4,0,H);snow.addColorStop(0,'rgba(246,252,253,.12)');snow.addColorStop(.55,'rgba(226,241,245,.3)');snow.addColorStop(1,'rgba(198,222,229,.42)');ctx.fillStyle=snow;ctx.beginPath();slices.forEach((s,i)=>i?ctx.lineTo(s.x-s.half,s.y):ctx.moveTo(s.x-s.half,s.y));for(let i=slices.length-1;i>=0;i--){const s=slices[i];ctx.lineTo(s.x+s.half,s.y)}ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(255,255,255,.2)';ctx.lineWidth=12;ctx.beginPath();slices.forEach((s,i)=>i?ctx.lineTo(s.x-s.half*.97,s.y):ctx.moveTo(s.x-s.half*.97,s.y));slices.slice().reverse().forEach(s=>ctx.lineTo(s.x+s.half*.97,s.y));ctx.stroke();ctx.strokeStyle='rgba(77,125,139,.1)';ctx.lineWidth=2;for(let row=5;row<21;row+=4){const s=slices[row];ctx.beginPath();ctx.moveTo(s.x-s.half*.78,s.y+2);ctx.quadraticCurveTo(s.x,s.y-5-s.t*8,s.x+s.half*.78,s.y+2);ctx.stroke()}ctx.restore()}
