/* Run finales: every line now builds toward an authored summit sequence rather
   than ending immediately when the distance counter reaches the base. */
let finaleActive=false,finaleStarted=false,finaleClears=0,finaleProfile=null,finaleBaseLength=0,finaleCourseLength=0;
const finaleProfiles={
  park:{name:'SUMMIT PARK SEND',brief:'Four features. One landing. Make the mountain remember it.',features:['gate','ramp','rail','summit']},
  glades:{name:'TREE-LINE ESCAPE',brief:'The trees close in. Find the last clean gap.',features:['avalanche','gate','ramp','summit']},
  steep:{name:'THE LAST PITCH',brief:'Commit to the fall line and hold your edge through the finish.',features:['ridge','ridge','ramp','summit']},
  spine:{name:'SPINE FINALE',brief:'No reset. No brakes. One final line off the ridge.',features:['ridge','gate','ramp','summit']},
  alpine:{name:'ABOVE TREELINE',brief:'The air is thin and the exit is wild. Send the summit.',features:['avalanche','ridge','ramp','summit']},
  bowl:{name:'BOWL EXIT',brief:'Carry speed across the bowl and launch into the last light.',features:['powder','gate','ramp','summit']}
};
const finaleVariants={
  park:[{name:'LAST LIGHT',brief:'The final light is dropping. Thread the park and stick the landing.',features:['gate','ramp','rail','summit']},{name:'LOCAL’S PARK LINE',brief:'The locals saved the best feature for last. Make it a clean style run.',features:['ramp','rail','ramp','summit']}],
  glades:[{name:'TREE-LINE ESCAPE',brief:'The trees close in. Find the last clean gap before the slab moves.',features:['avalanche','gate','ramp','summit']},{name:'POWDER EXIT',brief:'Fresh snow is sliding. Float the gap, then launch the last pitch.',features:['powder','avalanche','ramp','summit']}],
  steep:[{name:'PATROL CLOSURE',brief:'Patrol is closing the ridge behind you. Hold the edge through the pitch.',features:['ridge','ridge','ramp','summit']},{name:'ICE RUNOUT',brief:'The exit is hardpack and fast. Control the ridge, then commit.',features:['gate','ridge','ramp','summit']}],
  spine:[{name:'SPINE EXIT',brief:'No reset. No brakes. One final line off the ridge.',features:['ridge','gate','ramp','summit']},{name:'WIND LIP',brief:'The wind is moving across the spine. Pick the lip and stay centered.',features:['ridge','avalanche','ramp','summit']}],
  alpine:[{name:'ABOVE TREELINE',brief:'The air is thin and the exit is wild. Send the summit.',features:['avalanche','ridge','ramp','summit']},{name:'HIGH-ALPINE DROP',brief:'No trees, no cover, no second chance. Carry speed to the lip.',features:['ridge','gate','ramp','summit']}],
  bowl:[{name:'BOWL EXIT',brief:'Carry speed across the bowl and launch into the last light.',features:['powder','gate','ramp','summit']},{name:'POWDER WINDOW',brief:'The bowl is soft and wide. Float the line, then finish above the crowd.',features:['powder','powder','ramp','summit']}]
};
function finaleForRun(){const terrain=RUNS[routeIndex]?.[runIndex]?.terrain,base=finaleProfiles[terrain]||{name:'LAST CHAIR SEND',brief:'One final sequence. Leave your best line at the bottom.',features:['gate','ramp','summit']},options=finaleVariants[terrain]||[{name:'LAST LIGHT',brief:base.brief,features:base.features}],variant=options[(routeIndex+runIndex)%options.length];return{...base,...variant,name:`${ROUTES[routeIndex].name} · ${variant.name}`,features:variant.features.slice()}}
function finaleBanner(title,detail,active=true){let banner=$('finaleBanner');if(!banner){banner=document.createElement('div');banner.id='finaleBanner';banner.className='finale-banner';document.getElementById('game')?.append(banner)}banner.classList.toggle('visible',active);if(active)banner.innerHTML=`<small>ALPINE RUSH · FINAL SEQUENCE</small><strong>${title}</strong><span>${detail}</span>`}
function launchFinale(){if(finaleStarted||state!=='playing'||distance<courseLength*.84)return;finaleStarted=true;finaleActive=true;finaleProfile=finaleForRun();finaleClears=0;const oldLength=courseLength;finaleBaseLength=oldLength;courseLength=Math.round(courseLength*1.18);finaleProfile.features.forEach((feature,i)=>{const ahead=oldLength*.035+i*(courseLength-oldLength)*.22;const target=courseSample(Math.min(1,(distance+ahead)/courseLength));obstacles.push({type:'finaleFeature',feature,x:Math.max(.12,Math.min(.88,target.center+(i%2?.11:-.11)*(target.width*.9))),y:.035+i*.13,wobble:i*.9,hit:false,cleared:false,color:i%2?'#ffd260':'#62d9f5',side:i%2?1:-1});});finaleBanner(finaleProfile.name,finaleProfile.brief);toast('FINAL SEQUENCE',finaleProfile.name);beep(1180,.3);haptic([18,28,50]);}
