let finaleModeObjective=null;
function paintFinaleModeObjective(){if(!finaleModeObjective){finaleModeObjective=document.createElement('small');finaleModeObjective.id='finaleModeObjective';finaleModeObjective.className='finale-mode-objective';$('objective')?.append(finaleModeObjective)}const mode=AlpinePro.settings.mode||'freeride',labels={timetrial:'TIME TRIAL · BEAT YOUR GHOST',downhill:'DOWNHILL · HOLD MAX PACE',bigair:'BIG AIR · LAND THE BIGGEST TRICK',park:'PARK · BEAT THE TRICK TARGET',patrol:'PATROL · CLEAR THE GAUNTLET',slalom:'SLALOM · KEEP THE GATES CLEAN'};if(finaleModeObjective){finaleModeObjective.textContent=labels[mode]||`${mode.toUpperCase()} · FINISH CLEAN`;finaleModeObjective.hidden=!finaleActive}}
const finaleUpdate=update;update=function(dt){finaleUpdate(dt);if(state==='playing')launchFinale();if(finaleActive&&state==='playing'){ui.objectiveText.textContent='FINAL SEQUENCE';ui.objectiveProgress.textContent=`${finaleClears} / ${finaleProfile?.features?.length||0} FEATURES`;game.classList.add('finale-active');paintFinaleModeObjective()}else{game.classList.remove('finale-active');if(finaleModeObjective)finaleModeObjective.hidden=true}if(state==='finishing')finaleBanner('', '', false)};
const finaleClear=clearObstacle;clearObstacle=function(o,dx){if(o.type==='finaleFeature'){if(o.cleared||o.hit)return;o.cleared=true;finaleClears++;clears++;const points=(o.feature==='summit'?1100:o.feature==='ramp'?720:420)*combo;scorePop(points,o.x*W,o.y*H-18,o.feature==='summit'?'SUMMIT SEND':`${o.feature.toUpperCase()} CLEAR`);combo=Math.min(8,combo+1+(o.feature==='summit'?1:0));comboTime=4;bestCombo=Math.max(bestCombo,combo);burst(o.x*W,o.y*H,'#ffd260',o.feature==='summit'?42:24);toast(o.feature==='summit'?'SUMMIT SEND':'FINALE CLEAR',`+${points}`);beep(o.feature==='summit'?1240:900,.2);return}finaleClear(o,dx)};
const finaleHit=hitObstacle;hitObstacle=function(o,dx){if(o.type==='finaleFeature'&&o.feature==='ramp'&&player.jump===0){clearObstacle(o,dx);Object.assign(player,{jumpV:750+speed*35,jump:.1,spin:0,spinV:0,flip:0,flipV:0,grabTime:0,trickActive:false,compression:1});jumps++;toast('FINALE RAMP','TRICK TIME');beep(560,.12);return}if(o.type==='finaleFeature'&&o.feature==='summit'&&player.jump>38){clearObstacle(o,dx);return}finaleHit(o,dx)};
const finaleDraw=drawObstacle;drawObstacle=function(o){if(o.type!=='finaleFeature'){finaleDraw(o);return}if(o.y<.34||o.hit)return;const t=Math.max(0,Math.min(1,(o.y-.34)/.6)),scale=.22+t*.95;ctx.save();ctx.translate(o.x*W,o.y*H);ctx.scale(scale,scale);const color=o.feature==='summit'?'#ffd260':o.feature==='avalanche'?'#f4fbff':o.feature==='powder'?'#bcecf5':o.feature==='ridge'?'#ff7658':'#62d9f5';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=5;if(o.feature==='ramp'||o.feature==='summit'){ctx.beginPath();ctx.moveTo(-32,20);ctx.lineTo(18,-12);ctx.lineTo(34,20);ctx.closePath();ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke()}else if(o.feature==='gate'){ctx.beginPath();ctx.moveTo(-23,24);ctx.lineTo(-23,-27);ctx.moveTo(23,24);ctx.lineTo(23,-27);ctx.stroke();ctx.fillRect(-23,-27,46,10)}else if(o.feature==='avalanche'){ctx.beginPath();ctx.arc(0,8,30,0,Math.PI*2);ctx.fill();ctx.fillStyle='#325263';ctx.font='900 8px DM Sans';ctx.textAlign='center';ctx.fillText('SNOW SLAB',0,11)}else if(o.feature==='powder'){ctx.beginPath();ctx.ellipse(0,12,34,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';for(let i=-2;i<=2;i++){ctx.beginPath();ctx.arc(i*13,-12-Math.abs(i)*3,5,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#315263';ctx.font='900 8px DM Sans';ctx.textAlign='center';ctx.fillText('POWDER',0,13)}else{ctx.beginPath();ctx.moveTo(-28,21);ctx.lineTo(0,-30);ctx.lineTo(28,21);ctx.closePath();ctx.fill();ctx.fillStyle='#fff';ctx.font='900 8px DM Sans';ctx.textAlign='center';ctx.fillText('RIDGE',0,4)}ctx.restore()};
const finaleFinish=finish;finish=function(){const completedFinale=finaleActive&&courseComplete,bonus=completedFinale?finaleClears*300+1800:0;if(bonus)score+=bonus;finaleBanner('', '', false);finaleFinish();if(completedFinale){const result=$('battleResult');if(result)result.textContent=`${finaleProfile?.name||'FINAL SEQUENCE'} · ${finaleClears}/${finaleProfile?.features?.length||0} FEATURES CLEARED · SUMMIT BONUS +${bonus.toLocaleString()}`}};

/* Results recap: convert the many progression systems into one readable next goal. */
function paintMasteryRecap(){let recap=$('masteryRecap');if(!recap){recap=document.createElement('p');recap.id='masteryRecap';recap.className='mastery-recap';$('nextRunTip')?.before(recap)}const id=`${routeIndex}:${runIndex}:${AlpinePro.settings.mode}`,record=AlpinePro.medals()[id],medal=record?.rank?.toUpperCase()||'NO MEDAL',next=record?.rank==='gold'?'CHASE A FASTER TIME OR A CLEANER FINALE':record?.rank==='silver'?'ONE MORE CLEAN FEATURE FOR GOLD':record?.rank==='bronze'?'BUILD FLOW · THEN RETURN FOR SILVER':'CLEAR THE FINAL SEQUENCE TO EARN YOUR FIRST MEDAL';recap.textContent=`${ROUTES[routeIndex].name} / ${RUNS[routeIndex][runIndex].name.toUpperCase()} · ${medal} · ${next}`}
const recapFinish=finish;finish=function(){recapFinish();paintMasteryRecap()};
/* Region picker: keep the default experience Colorado-focused while preserving German routes on their own page. */
let routePage='colorado';
function isGermanRoute(index){return index>=5&&index<=7}
function applyRoutePage(){
  const german=routePage==='germany';
  document.querySelectorAll('.route-card').forEach((card,index)=>{const visible=isGermanRoute(index)===german;card.hidden=!visible;card.classList.toggle('selected',visible&&index===routeIndex)});
  const title=$('routePageTitle');if(title)title.innerHTML=german?'GERMANY<br>SELECT':'COLORADO<br>SELECT';
  const colorado=$('coloradoTab'),germany=$('germanyTab');if(colorado){colorado.classList.toggle('active',!german);colorado.setAttribute('aria-pressed',String(!german))}if(germany){germany.classList.toggle('active',german);germany.setAttribute('aria-pressed',String(german))}
}
function createRegionPicker(){
  const heading=ui.routes.querySelector('.menu-heading');if(!heading||$('regionNav'))return;
  heading.querySelector('h2')?.setAttribute('id','routePageTitle');
  const nav=document.createElement('nav');nav.id='regionNav';nav.className='region-nav';nav.setAttribute('aria-label','Mountain regions');nav.innerHTML='<button type="button" class="region-tab active" id="coloradoTab" aria-pressed="true">🇺🇸 COLORADO</button><button type="button" class="region-tab" id="germanyTab" aria-pressed="false">🇩🇪 GERMANY</button>';heading.append(nav);
  $('coloradoTab').onclick=()=>{routePage='colorado';if(isGermanRoute(routeIndex)){routeIndex=0;runIndex=0}applyRoutePage();populateRuns();updatePreview();updateTrailStatus(routeIndex);syncTrailAccess();updateMountainEvent();loadSnowReport(routeIndex)};
  $('germanyTab').onclick=()=>{routePage='germany';if(!isGermanRoute(routeIndex)){routeIndex=5;runIndex=0}applyRoutePage();populateRuns();updatePreview();updateTrailStatus(routeIndex);syncTrailAccess();updateMountainEvent();loadSnowReport(routeIndex)};
}
createRegionPicker();
const originalEnterRoutes=enterRoutes;enterRoutes=function(){routePage='colorado';if(isGermanRoute(routeIndex)){routeIndex=0;runIndex=0}originalEnterRoutes();createRegionPicker();applyRoutePage()};
/* Bind after all lifecycle wrappers are installed so title, results, and tutorial exits use the regional picker. */
$('enterButton').onclick=()=>{window.AlpineRushAudio?.intro?.();enterRoutes()};$('selectButton').onclick=enterRoutes;$('quitButton').onclick=()=>{hide(ui.pause);enterRoutes()};$('learnBackButton')?.addEventListener('click',enterRoutes);applyRoutePage();
/* The daily cup can land on a German line; switch pages with it instead of leaving the selected card hidden. */
cupButton?.addEventListener('click',()=>{routePage=isGermanRoute(cupRouteIndex)?'germany':'colorado';applyRoutePage()});

/* Chase-camera orientation is authoritative: negative screen Y is downhill.
   Keep ski tips and rider details pointed toward the horizon so every skier is
   visibly travelling down the same fall line. */
function drawDownhillSkiTips(edge){
  ctx.strokeStyle='#e9f7fa';ctx.lineWidth=1.5;ctx.beginPath();
  ctx.moveTo(-6,-1);ctx.quadraticCurveTo(-9+edge*2,-7,-4+edge*2,-9);
  ctx.moveTo(6,-1);ctx.quadraticCurveTo(9+edge*2,-7,4+edge*2,-9);ctx.stroke();
}
function drawDownhillSkier(x,y,tilt,color,isPlayer){
  ctx.save();ctx.translate(x,y);
  const edge=isPlayer?player.edge:Math.sin(player.anim*.45)*.2,crouch=isPlayer?player.compression:.2,turn=edge*.34,skin=isPlayer?SKINS[skinIndex]:{a:color,b:color},polePlant=Math.sin(player.anim*.72)*3;
  ctx.rotate(turn);ctx.lineCap='round';ctx.lineJoin='round';
  ctx.strokeStyle='#173244';ctx.lineWidth=3.4;ctx.beginPath();ctx.moveTo(-6,-2);ctx.lineTo(-7+edge*4,42);ctx.moveTo(6,-2);ctx.lineTo(7+edge*4,42);ctx.stroke();
  ctx.strokeStyle='#e9f7fa';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-6,7);ctx.lineTo(-7+edge*4,39);ctx.moveTo(6,7);ctx.lineTo(7+edge*4,39);ctx.stroke();drawDownhillSkiTips(edge);
  ctx.strokeStyle='#253e4d';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(-5,9+crouch*3);ctx.lineTo(-9-edge*3,21+crouch*4);ctx.lineTo(-7+edge*4,31);ctx.moveTo(5,9+crouch*3);ctx.lineTo(9-edge*3,21+crouch*4);ctx.lineTo(7+edge*4,31);ctx.stroke();
  const lean=edge*5,grad=ctx.createLinearGradient(-14,-16,14,13);grad.addColorStop(0,skin.a);grad.addColorStop(1,skin.b);ctx.fillStyle=grad;ctx.beginPath();ctx.moveTo(-12+lean,-12+crouch*2);ctx.quadraticCurveTo(lean,-17,12+lean,-12+crouch*2);ctx.lineTo(9,12+crouch*3);ctx.quadraticCurveTo(0,16+crouch*3,-9,12+crouch*3);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(255,255,255,.32)';ctx.lineWidth=1;ctx.stroke();
  ctx.strokeStyle='#263f4e';ctx.lineWidth=3.2;ctx.beginPath();ctx.moveTo(-10+lean,-8);ctx.lineTo(-19-edge*5,7);ctx.lineTo(-23-edge*7,27+polePlant);ctx.moveTo(10+lean,-8);ctx.lineTo(19-edge*5,7);ctx.lineTo(23-edge*7,27-polePlant);ctx.stroke();
  ctx.strokeStyle='#49636e';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(-23-edge*7,10);ctx.lineTo(-25-edge*7,36);ctx.moveTo(23-edge*7,10);ctx.lineTo(25-edge*7,36);ctx.stroke();
  ctx.fillStyle='#0b2332';ctx.beginPath();ctx.arc(lean,-21+crouch*2,9.5,0,Math.PI*2);ctx.fill();ctx.restore();
}
function drawRearRiderDetails(){
  const helmet=HELMETS[helmetIndex]||HELMETS[0],jacket=SKINS[skinIndex];ctx.save();ctx.lineCap='round';
  ctx.strokeStyle='rgba(255,255,255,.38)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-8,-9);ctx.lineTo(0,-4);ctx.lineTo(8,-9);ctx.stroke();
  ctx.strokeStyle='rgba(7,27,39,.45)';ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(0,11);ctx.stroke();ctx.fillStyle='rgba(7,27,39,.28)';ctx.beginPath();ctx.ellipse(0,7,8,5,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle=helmet;ctx.beginPath();ctx.arc(0,-21,9.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.4)';ctx.lineWidth=1;ctx.stroke();
  ctx.strokeStyle='rgba(7,27,39,.72)';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-8,-21);ctx.quadraticCurveTo(0,-19,8,-21);ctx.stroke();
  ctx.strokeStyle=GOGGLES[goggleIndex]||GOGGLES[0];ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(-8,-21);ctx.quadraticCurveTo(0,-19,8,-21);ctx.stroke();
  ctx.strokeStyle='rgba(7,27,39,.55)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-29);ctx.lineTo(0,-23);ctx.stroke();
  ctx.strokeStyle=SKINS[skinIndex].b;ctx.lineWidth=2;if(styleIndex===1){ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(9,9);ctx.stroke()}else if(styleIndex===2){ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(0,12);ctx.stroke();ctx.strokeStyle='rgba(255,255,255,.65)';ctx.beginPath();ctx.moveTo(-8,0);ctx.lineTo(8,0);ctx.stroke()}
  ctx.fillStyle=jacket.b;ctx.beginPath();ctx.arc(-10,7,3,0,Math.PI*2);ctx.fill();ctx.restore();
}
